// Build topology context for Topology Impact Agent
const trigger  = $('Execute Workflow Trigger').first().json;
const links    = $('Fetch Connected Links').all().map(i => i.json).filter(l => l.link_id);
const services = $('Fetch Dependent Services').all().map(i => i.json).filter(s => s.service_id);

// Extract unique neighboring devices
const neighbors = new Set();
links.forEach(l => {
  if (l.source_name !== trigger.device_name) neighbors.add(l.source_name);
  if (l.dest_name   !== trigger.device_name) neighbors.add(l.dest_name);
});

const context = {
  failed_device: {
    device_name:    trigger.device_name,
    alarm_type:     trigger.alarm_type,
    severity:       trigger.severity,
    interface_name: trigger.interface_name || 'N/A',
    alarm_id:       trigger.alarm_id,
    incident_id:    trigger.incident_id,
  },
  connected_links: links.map(l => ({
    link_name:    l.link_name,
    link_type:    l.link_type,
    capacity_gbps: l.capacity_gbps,
    source:       l.source_name,
    destination:  l.dest_name,
    source_role:  l.source_role,
    dest_role:    l.dest_role,
  })),
  neighboring_devices: Array.from(neighbors),
  dependent_services: services.map(s => ({
    service_name: s.service_name,
    service_type: s.service_type,
    customer:     s.customer_name,
    sla_tier:     s.sla_tier,
    status:       s.status,
  })),
  total_links:    links.length,
  total_services: services.length,
  agent_started_at: new Date().toISOString(),
};

return [{ json: { context } }];

// Parse and validate Topology Agent output
const raw         = $input.first().json;
const agentOutput = typeof raw.text === 'string' ? raw.text : (typeof raw.content === 'string' ? raw.content : '');
// chainLlm runs with onError=continue, so a failed LLM call arrives here as { error }
const llmError    = raw.error ? (typeof raw.error === 'string' ? raw.error : JSON.stringify(raw.error)) : null;
const context     = $('Build Topology Context').first().json.context;

let parsed;
try {
  if (llmError) throw new Error('LLM call failed: ' + llmError);
  const cleaned = agentOutput.replace(/```json?\n?/g, '').replace(/```/g, '').trim();
  parsed = JSON.parse(cleaned);
} catch (e) {
  parsed = {
    impact_level:                  'Unknown',
    affected_nodes:                [context.failed_device.device_name],
    affected_links:                [],
    affected_services:             context.dependent_services.map(s => ({ service_name: s.service_name, customer: s.customer, impact_type: 'Unknown', sla_breach_risk: false })),
    cascade_risk:                  'Analysis failed — manual assessment required',
    traffic_rerouting_possible:    false,
    redundant_paths_available:     false,
    estimated_customers_affected:  0,
    topology_analysis_notes:       'Fallback: LLM output parse error — ' + e.message,
    parse_error: e.message,
  };
}

const validLevels = ['Critical','High','Medium','Low','None','Unknown'];
if (!validLevels.includes(parsed.impact_level)) parsed.impact_level = 'Unknown';
if (!Array.isArray(parsed.affected_nodes))    parsed.affected_nodes = [];
if (!Array.isArray(parsed.affected_links))    parsed.affected_links = [];
if (!Array.isArray(parsed.affected_services)) parsed.affected_services = [];

return [{
  json: {
    ...parsed,
    alarm_id:     context.failed_device.alarm_id,
    incident_id:  context.failed_device.incident_id,
    agent_name:   'topology_impact',
    completed_at: new Date().toISOString(),
  }
}];
